16:     /// <summary>
17:     /// A huge plant's DESIRED footprint (ground-contact cells) and its selection rect, both from the picture the engine
18:     /// draws right now. Attached at startup to every plant def carrying RM_HugePlantExtension (HugeThingsStartup).
19:     ///
20:     /// It never spawns anything itself: it hands its desired cells to MapComponent_HugeFootprints, which owns the map-wide
21:     /// claim ledger, plans which cells may safely close, and keeps exactly one blocker per claimed cell. Holds no saved
22:     /// state; the map component rebuilds everything from the plants and the blockers on load.
23:     /// </summary>
24:     public class CompHugeFootprint : ThingComp
25:     {
26:         // Plant.Print's random draws for this cell (see RM_HugeFootprintKernel's header). Replayed on each use: the variant
27:         // index depends on the CURRENT graphic's sub-graphic count.
28:         private float jitterX, jitterZ;
29:         private bool flip;
30:         private int variantIndex;
31: 
32:         private readonly SignatureCache<CellRect> selectCache = new SignatureCache<CellRect>();
33:         private FootprintSignature lastTaken;
34:         private bool takenOnce;
35: 
36:         public RM_HugePlantExtension Ext => parent.def.GetModExtension<RM_HugePlantExtension>();
37: 
38:         public Plant Plant => parent as Plant;
39: 
40:         public int OwnerId => parent.thingIDNumber;
41: 
42:         /// <summary>Replays Plant.Print's Rand sequence for this cell: jitter, flipUv, Graphic_Random index. The global Rand
43:         /// state is always restored, even if a graphic getter throws (GPT review #16).</summary>
44:         private void Roll()
45:         {
46:             Plant p = Plant;
47:             if (p == null || !p.Spawned) return;
48:             Graphic g = p.Graphic;
49:             int n = g is Graphic_Random gr ? gr.SubGraphicsCount : 0;
50:             Rand.PushState();
51:             try
52:             {
53:                 Rand.Seed = p.Position.GetHashCode();
54:                 Vector3 j = Gen.RandomHorizontalVector(0.05f);
55:                 bool f = Rand.Bool;
56:                 int idx = n > 0 ? Rand.Range(0, n) : 0;
57:                 jitterX = j.x;
58:                 jitterZ = j.z;
59:                 flip = f;
60:                 variantIndex = idx;
61:             }
62:             finally
63:             {
64:                 Rand.PopState();
65:             }
66:         }
67: 
68:         /// <summary>The measured variant of the picture actually drawn, or the union stand-in when the drawn texture was
69:         /// never measured (an immature or leafless graphic, an art override).</summary>
70:         private HugePlantVariant DrawnVariant(RM_HugePlantExtension ext, out bool measured, out int maskId, FootprintWorkBudget budget = null)
71:         {
72:             Graphic g = Plant.Graphic;
73:             if (g is Graphic_Random gr && gr.SubGraphicsCount > 0) g = gr.SubGraphicAtIndex(variantIndex);
74:             string path = g?.path;
75:             string name = path == null ? null : path.Substring(path.LastIndexOf('/') + 1);
76:             HugePlantVariant v = ext.Find(name, budget);
77:             budget?.Spend(ext.variants.Count);
78:             measured = v != null;
79:             maskId = measured ? ext.variants.IndexOf(v) + 1 : 0;
80:             return v ?? ext.GetUnion(budget);
81:         }
82: 
83:         /// <summary>Everything the footprint and the selection rect depend on right now.</summary>
84:         public FootprintSignature Signature(out HugeMask mask, FootprintWorkBudget budget = null)
85:         {
