100:                 BlockScale = RM_HugeThingsSettings.plantTrunkScale,
101:                 Flip = flip,
102:                 Measured = measured,
103:                 Blocking = RM_HugeThingsSettings.PlantTrunkActive && ext.blockingSupported,
104:                 Selecting = RM_HugeThingsSettings.PlantSelectionActive,
105:                 OldEnough = p.Growth >= ext.minGrowthToBlock,
106:             };
107:         }
108: 
109:         private static HugeQuad QuadOf(FootprintSignature s)
