111: 
112:         /// <summary>Ground-contact cells wanted now, as cell keys (empty when blocking is off or the plant is too young).</summary>
113:         public List<long> DesiredKeys(FootprintWorkBudget budget = null)
114:         {
115:             Plant p = Plant;
