121:         private static List<long> DesiredKeys(FootprintSignature s, HugeMask m, FootprintWorkBudget budget = null)
122:         {
123:             if (!s.Blocking || !s.OldEnough) return new List<long>();
124:             return RM_HugeFootprintKernel.ContactCells(s.RootX, s.RootZ, QuadOf(s), s.BlockScale, s.Flip, m, budget);
125:         }
126: 
127:         /// <summary>The cells this plant could EVER claim at full growth and the largest setting: the bounded placement-flag window
