8: namespace RimMandrake.HugeThings
9: {
10:     /// <summary>Pure IL transformation shared by production and the mutation harness. Returns original instructions
11:     /// unchanged unless exactly the two measured contact calls and their operands match.</summary>
12:     public static class PlantCutToilRewrite
13:     {
14:         private static bool Constant(CodeInstruction code, int value)
15:         {
16:             if (code.opcode == OpCodes.Ldc_I4 || code.opcode == OpCodes.Ldc_I4_S) return Convert.ToInt32(code.operand) == value;
17:             OpCode[] small = { OpCodes.Ldc_I4_0, OpCodes.Ldc_I4_1, OpCodes.Ldc_I4_2, OpCodes.Ldc_I4_3, OpCodes.Ldc_I4_4,
18:                 OpCodes.Ldc_I4_5, OpCodes.Ldc_I4_6, OpCodes.Ldc_I4_7, OpCodes.Ldc_I4_8 };
19:             return value >= 0 && value < small.Length && code.opcode == small[value];
20:         }
21: 
22:         public static List<CodeInstruction> Rewrite(List<CodeInstruction> code, FieldInfo driver, MethodInfo go, MethodInfo touch,
23:             MethodInfo goWrapper, MethodInfo touchWrapper, int target, int mode, out bool accepted)
24:         {
25:             accepted = false;
26:             if (driver == null || go == null || touch == null || goWrapper == null || touchWrapper == null) return code;
27:             var gotos = new List<int>(); var contacts = new List<int>();
28:             for (int i = 0; i < code.Count; i++)
29:             {
30:                 if (Equals(code[i].operand, go)) gotos.Add(i);
31:                 if (Equals(code[i].operand, touch)) contacts.Add(i);
32:             }
33:             if (gotos.Count != 1 || contacts.Count != 1) return code;
34:             int g = gotos[0], c = contacts[0];
35:             if (code[g].blocks.Count != 0 || code[c].blocks.Count != 0) return code;
36:             if (g < 3 || c < 2 || !Constant(code[g-3], target) || !Constant(code[g-2], mode) || !Constant(code[g-1], 0) ||
37:                 !Constant(code[c-2], target) || !Constant(code[c-1], mode)) return code;
38:             var replacements = new Dictionary<int, MethodInfo> { [g] = goWrapper, [c] = touchWrapper };
39:             var result = new List<CodeInstruction>();
40:             for (int i = 0; i < code.Count; i++)
41:             {
42:                 if (!replacements.TryGetValue(i, out MethodInfo wrapper)) { result.Add(code[i]); continue; }
43:                 var load = new CodeInstruction(OpCodes.Ldarg_0);
44:                 load.labels.AddRange(code[i].labels);
45:                 load.blocks.AddRange(code[i].blocks);
46:                 result.Add(load);
47:                 result.Add(new CodeInstruction(OpCodes.Ldfld, driver));
48:                 result.Add(new CodeInstruction(OpCodes.Call, wrapper));
49:             }
50:             accepted = true;
51:             return result;
52:         }
53:     }
54: }

