182:         /// <summary>Accept empty, passable, unprotected wanted cells in deterministic order. Access is deliberately
183:         /// not a placement constraint: growing trunks can seal doors and disconnect rooms. Occupied cells stay pending.</summary>
184:         public static List<long> Plan(IList<long> wanted, Func<long, CellFlags> flagsAt, CellBox window, FootprintWorkBudget budget = null)
185:         {
186:             var accepted = new List<long>();
187:             if (wanted == null || wanted.Count == 0) return accepted;
188:             long width = (long)window.MaxX - window.MinX + 1, height = (long)window.MaxZ - window.MinZ + 1;
189:             if (width <= 0 || height <= 0 || width > MaxWindowCells || height > MaxWindowCells || width * height > MaxWindowCells)
190:                 return accepted;
