192:             var order = new List<long>(new HashSet<long>(wanted));
193:             order.Sort((a, b) =>
194:             {
195:                 int z = RM_HugeFootprintKernel.KeyZ(a).CompareTo(RM_HugeFootprintKernel.KeyZ(b));
196:                 return z != 0 ? z : RM_HugeFootprintKernel.KeyX(a).CompareTo(RM_HugeFootprintKernel.KeyX(b));
197:             });
198:             foreach (long cell in order)
199:             {
200:                 budget?.Spend();
201:                 if (!window.Contains(RM_HugeFootprintKernel.KeyX(cell), RM_HugeFootprintKernel.KeyZ(cell))) continue;
202:                 CellFlags flags = flagsAt(cell);
203:                 if ((flags & CellFlags.Passable) != 0 && (flags & (CellFlags.Pawn | CellFlags.Item | CellFlags.Protected)) == 0)
