226:     /// <summary>
227:     /// Owner ruling 2026-10-07 21:08 (decision taken by question card): a footprint cell held only by items closes after its
228:     /// items are pushed, gently, to the nearest free valid cell that is in NO footprint (claimed by any plant); pawns are
229:     /// never moved. Every item of a cell must fit or none moves (the cell then stays open). Capacity is shared across the
230:     /// whole pass so two cells never overfill one destination. Search is a 4-connected BFS over cells with capacity >= 0
231:     /// (passable ground), preferred cells first at each distance, then key order: deterministic.
232:     /// </summary>
233:     public static class ItemMover
234:     {
235:         public const int MaxRadius = 12;
236: 
237:         /// <summary>
238:         /// For each source cell (in key order) with itemCounts[cell] items, a destination per item, or no entry when they
239:         /// do not all fit. capacity(k): how many more items cell k takes (-1 = not a valid cell at all). excluded(k): in some
240:         /// footprint. preferred(src, k): e.g. the same stockpile as the source.
241:         /// </summary>
242:         public static Dictionary<long, List<long>> Assign(IDictionary<long, int> itemCounts, Func<long, int> capacity,
243:                                                           Func<long, bool> excluded, Func<long, long, bool> preferred, FootprintWorkBudget budget = null)
244:         {
245:             Dictionary<long, List<long>> outMoves = new Dictionary<long, List<long>>();
246:             Dictionary<long, int> used = new Dictionary<long, int>();
247:             budget?.Spend(8L * itemCounts.Count * (1 + (long)Math.Ceiling(Math.Log(itemCounts.Count + 1, 2))));
248:             List<long> srcs = new List<long>(itemCounts.Keys);
249:             srcs.Sort();
250:             foreach (long src in srcs)
251:             {
252:                 int need = itemCounts[src];
253:                 if (need <= 0) continue;
254:                 List<long> dests = new List<long>();
255:                 Dictionary<long, int> take = new Dictionary<long, int>();
256:                 foreach (long k in Ring(src, capacity, preferred, budget))
257:                 {
258:                     if (k == src || excluded(k)) continue;
259:                     int cap = capacity(k) - (used.TryGetValue(k, out int u) ? u : 0) - (take.TryGetValue(k, out int t) ? t : 0);
260:                     while (cap > 0 && dests.Count < need)
261:                     {
262:                         budget?.Spend();
263:                         dests.Add(k);
264:                         take[k] = (take.TryGetValue(k, out int t2) ? t2 : 0) + 1;
265:                         cap--;
266:                     }
267:                     if (dests.Count == need) break;
268:                 }
269:                 if (dests.Count < need) continue;
270:                 foreach (KeyValuePair<long, int> kv in take) used[kv.Key] = (used.TryGetValue(kv.Key, out int u2) ? u2 : 0) + kv.Value;
271:                 outMoves[src] = dests;
272:             }
273:             return outMoves;
274:         }
