276:         /// <summary>
277:         /// PLANT_FOOTPRINT_HARDENING_1 (C3.2): Assign reserves destinations BEFORE the planner runs, so a source the planner then
278:         /// refuses kept its reservation and could starve another source forever. Assign and plan are iterated: a refused source
279:         /// is dropped and the rest re-assigned, until every source holding a reservation is one the planner accepts. plan(moves)
280:         /// returns the accepted cells for that move set. Terminates: each round removes at least one source.
281:         /// </summary>
282:         public static Dictionary<long, List<long>> AssignAndPlan(IDictionary<long, int> itemCounts, Func<long, int> capacity,
283:                                                                  Func<long, bool> excluded, Func<long, long, bool> preferred,
284:                                                                  Func<Dictionary<long, List<long>>, List<long>> plan,
285:                                                                  out List<long> accepted, FootprintWorkBudget budget = null)
286:         {
287:             budget?.Spend(itemCounts.Count);
288:             var counts = new Dictionary<long, int>(itemCounts);
289:             while (true)
290:             {
291:                 Dictionary<long, List<long>> moves = Assign(counts, capacity, excluded, preferred, budget);
292:                 accepted = plan(moves);
293:                 var ok = new HashSet<long>(accepted);
294:                 var refused = new List<long>();
295:                 foreach (long src in moves.Keys) if (!ok.Contains(src)) refused.Add(src);
296:                 if (refused.Count == 0) return moves;
297:                 foreach (long src in refused) counts.Remove(src);
298:             }
299:         }
