301:         /// <summary>Cells reachable from src over capacity >= 0 ground, nearest first (BFS layers), preferred first within a
302:         /// layer, then by key.</summary>
303:         private static IEnumerable<long> Ring(long src, Func<long, int> capacity, Func<long, long, bool> preferred, FootprintWorkBudget budget)
304:         {
305:             HashSet<long> seen = new HashSet<long> { src };
306:             List<long> layer = new List<long> { src };
307:             for (int d = 0; d < MaxRadius && layer.Count > 0; d++)
308:             {
309:                 List<long> next = new List<long>();
310:                 foreach (long k in layer)
311:                 {
312:                     budget?.Spend();
313:                     int x = RM_HugeFootprintKernel.KeyX(k), z = RM_HugeFootprintKernel.KeyZ(k);
314:                     long[] ns = { RM_HugeFootprintKernel.Key(x + 1, z), RM_HugeFootprintKernel.Key(x - 1, z),
315:                                   RM_HugeFootprintKernel.Key(x, z + 1), RM_HugeFootprintKernel.Key(x, z - 1) };
316:                     foreach (long n in ns)
317:                     {
318:                         budget?.Spend();
319:                         if (seen.Add(n) && capacity(n) >= 0) next.Add(n);
320:                     }
321:                 }
322:                 budget?.Spend(8L * next.Count * (1 + (long)Math.Ceiling(Math.Log(next.Count + 1, 2))));
323:                 next.Sort((a, b) =>
324:                 {
325:                     bool pa = preferred != null && preferred(src, a), pb = preferred != null && preferred(src, b);
326:                     if (pa != pb) return pa ? -1 : 1;
327:                     return a.CompareTo(b);
328:                 });
329:                 foreach (long k in next) yield return k;
330:                 layer = next;
331:             }
332:         }
333:     }
