169:         public override void MapComponentTick()
170:         {
171:             base.MapComponentTick();
172:             if (!initialized) return;
173:             // A child quota gives every loaded map a share; the parent enforces the aggregate cap even if maps
174:             // are added/removed during a tick. An early map cannot consume a later map's entire allowance.
175:             work = new FootprintWorkBudget(WorkUnitsPerTick / System.Math.Max(1, Find.Maps.Count), BudgetForTick());
176:             ownersVisited = 0;
177:             try
178:             {
179:                 // Alternate bounded removal and owner work so neither stream can starve the other.
180:                 int visits = System.Math.Min(RefreshesPerTick, readyOwners.Count);
181:                 for (int n = 0; n < visits; n++)
182:                 {
183:                     DrainRemoval();
184:                     work.Spend();
185:                     if (!readyOwners.Next(out int id)) break;
186:                     if (!comps.TryGetValue(id, out CompHugeFootprint c)) continue;
187:                     ownersVisited++;
188:                     try
189:                     {
190:                         bool refresh = dirty.Contains(id) || !ownerGeneration.TryGetValue(id, out int generation) || generation != refreshGeneration;
191:                         if (refresh)
