331:         /// <summary>Take a plant's current desired cells into the ledger; free what it no longer wants.</summary>
332:         private void Take(CompHugeFootprint c)
333:         {
334:             List<long> claimed = new List<long>(), freed = new List<long>();
335:             List<long> want = c.DesiredKeys(work);
336:             work?.Spend(want.Count);
337:             List<long> keep = new List<long>(want.Count);
338:             foreach (long k in want) { work?.Spend(); if (Cell(k).InBounds(map)) keep.Add(k); }
339:             // Atomic ledger/open/relabel transaction: reserve its bounded copies, comparisons and affected-cell work
340:             // BEFORE mutating any ownership. If it cannot fit, leave the previous footprint intact and dirty.
341:             long count = (long)ledger.CountOf(c.OwnerId) + keep.Count + 1;
342:             work?.Spend(32 * count * (1 + (long)System.Math.Ceiling(System.Math.Log(count + 1, 2))));
343:             HashSet<long> before = new HashSet<long>(ledger.CellsOf(c.OwnerId));
344:             ledger.Set(c.OwnerId, keep, claimed, freed);
345:             Open(freed);
346:             foreach (long k in claimed) if (!realized.ContainsKey(k)) pending.Add(k);
347:             before.UnionWith(keep);
348:             foreach (long k in before) { QueuePending(k); RelabelCell(k); }
349:             c.MarkTaken();
350:         }
