432:         /// <summary>Owner ruling 2026-10-07 21:08: for each wanted cell held ONLY by items (no pawn, nothing protected), a
433:         /// destination per item in the nearest free valid cell outside every footprint, preferring the source's own storage;
434:         /// at most once per PendingRetryInterval per cell. Cells whose items do not all fit are left out (they stay open).</summary>
435:         private Dictionary<long, List<long>> PlanItemMoves(List<long> mine, Dictionary<long, CellFlags> flags, CellBox window,
436:                                                            out List<long> accepted)
437:         {
438:             List<long> Plan(Dictionary<long, List<long>> mv)
439:             {
440:                 return Planner.Plan(mine, k =>
441:                 {
442:                     if (!flags.TryGetValue(k, out CellFlags f)) return CellFlags.Passable;
443:                     return mv.ContainsKey(k) ? f & ~CellFlags.Item : f;   // movable: plan it as if clear
444:                 }, window, work);
445:             }
446:             Dictionary<long, int> counts = new Dictionary<long, int>();
447:             if (RM_HugeThingsSettings.PlantItemPushActive)   // Mod Settings off: the cell stays open
448:             {
449:                 int now = Find.TickManager.TicksGame;
450:                 foreach (long k in mine)
451:                 {
452:                     work?.Spend();
453:                     if (!flags.TryGetValue(k, out CellFlags f) || f != (CellFlags.Passable | CellFlags.Item)) continue;
454:                     if (lastMoveTick.TryGetValue(k, out int t) && now - t < PendingRetryInterval) continue;
455:                     if (HoldsQuestItem(Cell(k))) continue;   // A3.6: never move a quest thing; the cell is deferred (stays open)
456:                     counts[k] = Cell(k).GetItemCount(map);
457:                 }
458:             }
459:             if (counts.Count == 0)
460:             {
461:                 accepted = Plan(new Dictionary<long, List<long>>());
462:                 return new Dictionary<long, List<long>>();
463:             }
464:             return ItemMover.AssignAndPlan(counts, Capacity, k => ledger.IsClaimed(k),
465:                                            (src, k) => Cell(src).GetSlotGroup(map) == Cell(k).GetSlotGroup(map), Plan, out accepted, work);
