473:             if (c.InBounds(map)) work?.Spend(c.GetThingList(map).Count + 1L);
474:             if (!c.InBounds(map) || !c.Standable(map) || realized.ContainsKey(k)) return -1;
475:             return System.Math.Max(0, c.GetMaxItemsAllowedInCell(map) - c.GetItemCount(map));
476:         }
