478:         /// <summary>Move every item off k to its planned cell, keeping each Thing (so its forbidden state, stack and
479:         /// quality) and destroying nothing; an item that cannot be placed goes back where it was. Quiet: no letter, no
480:         /// message. True only when the cell is left with no items.</summary>
481:         private bool MoveItems(long k, List<long> dests)
482:         {
483:             IntVec3 src = Cell(k);
484:             // Reserve the whole mutation first; never interrupt between despawning an item and replacing it.
485:             work?.Spend(32L * (src.GetThingList(map).Count + dests.Count + 1));
486:             lastMoveTick[k] = Find.TickManager.TicksGame;
487:             List<Thing> items = new List<Thing>();
488:             foreach (Thing t in src.GetThingList(map)) if (t.def.category == ThingCategory.Item) items.Add(t);
489:             if (items.Count != dests.Count) return false;   // the cell changed since planning: try again later
490:             if (HoldsQuestItem(src)) return false;          // A3.6: a quest thing arrived since planning: defer
