602:                     }
603:                     CellFlags fl = c.Walkable(map) ? CellFlags.Passable : CellFlags.None;
604:                     if (protectedCells.Contains(c)) fl |= CellFlags.Protected;
605:                     List<Thing> list = c.GetThingList(map);
606:                     for (int i = 0; i < list.Count; i++)
607:                     {
608:                         work?.Spend();
609:                         Thing t = list[i];
610:                         if (t is Pawn) fl |= CellFlags.Pawn;
611:                         else if (t.def.category == ThingCategory.Item) fl |= CellFlags.Item;
612:                         else if (t.def.category == ThingCategory.Building || t.def.IsBlueprint || t.def.IsFrame || !t.def.destroyable)
613:                             fl |= CellFlags.Protected;
614:                         else if (t is Plant pl && (pl.def.plant.IsTree || pl.def.HasModExtension<RM_HugePlantExtension>()))
615:                             fl |= CellFlags.Protected;
616:                     }
617:                     f[k] = fl;
618:                 }
619:             }
620:             return f;
621:         }
