686:         /// <summary>
687:         /// Giant plants' solid cells in an area, for a titan smashing through (HugeTitan kernel, GiantSmash.Owners): every realized
688:         /// trunk cell (owned by the plant its hits forward to) and every giant's own cell. Walks the area's cells, never the map.
689:         /// </summary>
690:         public List<SolidCell> SolidCellsIn(CellRect area, Dictionary<int, Plant> plants)
691:         {
692:             List<SolidCell> cells = new List<SolidCell>();
693:             foreach (IntVec3 c in area)
694:             {
695:                 if (!c.InBounds(map)) continue;
696:                 if (realized.TryGetValue(Key(c), out Building_TrunkBlocker b) && b.owner != null && !b.owner.Destroyed && b.owner.Spawned)
697:                 {
698:                     cells.Add(new SolidCell(c.x, c.z, b.owner.thingIDNumber));
699:                     plants[b.owner.thingIDNumber] = b.owner;
700:                 }
701:                 List<Thing> things = c.GetThingList(map);
702:                 for (int i = 0; i < things.Count; i++)
703:                 {
704:                     if (things[i] is Plant p && !p.Destroyed && comps.ContainsKey(p.thingIDNumber))
705:                     {
706:                         cells.Add(new SolidCell(c.x, c.z, p.thingIDNumber));
707:                         plants[p.thingIDNumber] = p;
708:                     }
709:                 }
710:             }
711:             return cells;
712:         }
