743:         /// <summary>HUGETHINGS_TRUNK_ZERO_BLOCKERS_1: read-only state of the huge plant rooted at `cell`, for a bridge probe
744:         /// (jawa/static_call RimMandrake.HugeThings.MapComponent_HugeFootprints DebugPlantState current|x,z): is it registered,
745:         /// what the comp computes, how many of its claimed cells are realized or pending, and for the pending ones what the
746:         /// planner sees (flag counts) and how many a dry Planner.Plan would accept now. Changes nothing.</summary>
747:         public static string DebugPlantState(Map map, IntVec3 cell)
748:         {
749:             MapComponent_HugeFootprints mc = map?.GetComponent<MapComponent_HugeFootprints>();
750:             if (mc == null) return "FAIL no component";
751:             if (!cell.InBounds(map)) return "FAIL cell out of bounds";
752:             CompHugeFootprint comp = null;
753:             foreach (Thing t in cell.GetThingList(map))
754:             {
755:                 if (t is Plant && t.Position == cell && (comp = t.TryGetComp<CompHugeFootprint>()) != null) break;
756:             }
757:             string head = "initialized=" + mc.initialized + " trunkActive=" + RM_HugeThingsSettings.PlantTrunkActive
758:                 + " giants=" + mc.comps.Count + " realizedAll=" + mc.realized.Count + " pendingAll=" + mc.pending.Count;
759:             if (comp == null) return "FAIL no huge plant with CompHugeFootprint at " + cell + " | " + head;
760:             int id = comp.OwnerId;
761:             List<long> mine = new List<long>(mc.ledger.CellsOf(id));
762:             int real = 0, pend = 0;
763:             List<long> pendList = new List<long>();
764:             foreach (long k in mine)
765:             {
766:                 if (mc.realized.ContainsKey(k)) real++;
767:                 if (mc.pending.Contains(k)) { pend++; pendList.Add(k); }
768:             }
769:             string s = "plant=" + comp.parent.ThingID + " registered=" + mc.comps.ContainsKey(id) + " dirtyQueued=" + mc.dirty.Contains(id)
770:                 + " claimed=" + mine.Count + " realized=" + real + " pending=" + pend + " | " + comp.DebugDescribe() + " | " + head;
771:             if (pendList.Count == 0) return s;
772:             pendList.Sort();
773:             HashSet<long> occupied = mc.OccupiedPawnCells();
774:             CellBox window = Planner.Window(comp.MaxKeys(), Key(comp.parent.Position));
775:             Dictionary<long, CellFlags> flags = mc.Flags(window);
776:             foreach (long k in occupied)
777:                 if (flags.TryGetValue(k, out CellFlags f)) flags[k] = f | CellFlags.Pawn;
778:             int notPass = 0, pawn = 0, item = 0, prot = 0, outside = 0;
779:             foreach (long k in pendList)
780:             {
781:                 if (!window.Contains(RM_HugeFootprintKernel.KeyX(k), RM_HugeFootprintKernel.KeyZ(k))) outside++;
782:                 CellFlags f = flags.TryGetValue(k, out CellFlags v) ? v : CellFlags.Passable;
783:                 if ((f & CellFlags.Passable) == 0) notPass++;
784:                 if ((f & CellFlags.Pawn) != 0) pawn++;
785:                 if ((f & CellFlags.Item) != 0) item++;
786:                 if ((f & CellFlags.Protected) != 0) prot++;
787:             }
788:             int accept = Planner.Plan(pendList, k => flags.TryGetValue(k, out CellFlags f) ? f : CellFlags.None, window).Count;
789:             return s + " | pendingFlags notPassable=" + notPass + " pawn=" + pawn + " item=" + item + " protected=" + prot
790:                 + " outsideWindow=" + outside + " window=" + window.MinX + "," + window.MinZ + ".." + window.MaxX + "," + window.MaxZ
791:                 + " dryPlanAccepts=" + accept;
792:         }
793:     }
794: }
