1: #!/usr/bin/env python3
2: """Def + structure lint for Huge Things (mandrake.rm.hugethings), no game.
3: 
4:     python3 src/RimMandrake/Utils/selftest_hugethings_lint.py      -> "N/N PASS", exit 0
5: 
6:   * kernel guard: Source/Kernel/*.cs is engine-free and compiled into BOTH the mod and the fuzz project;
7:   * every plant that opts in (an RM_HugePlantExtension anywhere in src/, by patch or def) carries generated data: a
8:     measuredSize and >= 1 variant, each variant with a texture, an opaque box inside 0..1 and contact cells, the root
9:     cell never among them; and the file it lives in carries the measure tool's GENERATED header;
10:   * no hand-tuned leftovers anywhere in src/: trunkWidth / trunkDepth / stemHeight (the pre-2026-10-07 rect footprint);
11:   * the blocker def keeps the ruled engine contract (impassable edifice, holdsRoof false, partial fill < 1, hit points
12:     off) -- GPT review #17: rooms/roofs/LOS behaviour is pinned, fill is never raised to 1 to fake solidity.
13: Sanity probe: the opt-in sweep must see the nine Rot giants.
14: """
15: import glob
16: import os
17: import re
18: import sys
19: import xml.etree.ElementTree as ET
20: 
21: HERE = os.path.dirname(os.path.abspath(__file__))
22: SRC = os.path.normpath(os.path.join(HERE, "..", ".."))
23: MOD = os.path.join(SRC, "RimMandrake", "HugeThings")
24: sys.path.insert(0, HERE)
25: from lint_kernel_guards import kernel_guards  # noqa: E402
26: 
27: EXT = "RimMandrake.HugeThings.RM_HugePlantExtension"
28: GENERATED = "GENERATED by `python3 src/RimMandrake/HugeThings/measure_huge_plant_masks.py`"
29: LEFTOVERS = ("trunkWidth", "trunkDepth", "stemHeight")
30: PROBE = {"RM_AgariluxPrime", "RM_DribblingCap", "RM_Nogtyl", "RM_Arpeau", "RM_ArbuscularMycorrhiza",
31:          "RM_GiantAgarilux", "RM_PaleTree"}   # AgaricusDomeCap, WitchesOyster shrank below 6 wide 2026-11-03
32: 
33: 
34: def xml_files():
35:     for p in glob.glob(os.path.join(SRC, "**", "*.xml"), recursive=True):
36:         if "/obj/" not in p and "/bin/" not in p:
37:             yield p
38: 
39: 
40: def opt_ins():
41:     """[(file, defName, li element)] for every RM_HugePlantExtension in src/ XML."""
42:     out = []
43:     for p in xml_files():
44:         txt = open(p, encoding="utf-8", errors="replace").read()
45:         if EXT not in txt:
46:             continue
47:         root = ET.parse(p).getroot()
48:         for el in root.iter():
49:             for li in el.findall("li"):
50:                 if li.get("Class") == EXT:
51:                     dn = None
52:                     if root.tag == "Patch":
53:                         for op in root:
54:                             if li in list(op.iter()):
55:                                 m = re.search(r'defName="([^"]+)"', op.findtext("xpath") or "")
56:                                 dn = m.group(1) if m else None
57:                     else:
58:                         dn = el.findtext("../defName") or None
59:                     out.append((p, dn, li))
60:     return out
61: 
