77: @test
78: def every_opt_in_has_generated_masks():
79:     ins = opt_ins()
80:     seen = {dn for _p, dn, _li in ins}
81:     assert PROBE <= seen, "sanity probe: the sweep misses %r (saw %d opt-ins)" % (sorted(PROBE - seen), len(ins))
82:     bad = []
