import json,hashlib,xml.etree.ElementTree as ET
from pathlib import Path,PureWindowsPath
raw=Path(\"whittle/ht-trunk-doors/evidence/raw\");j=json.loads((raw/\"live-after9/trunk-doors.json\").read_text())
for x in j[\"supplement_saves\"]:
 w=PureWindowsPath(x[\"path\"]);p=Path(\"/mnt/c\").joinpath(*w.parts[1:]); b=p.read_bytes();print(\"OBSERVATION\",w.name,\"bytes\",len(b),\"sha256\",hashlib.sha256(b).hexdigest())
 try:
  root=ET.fromstring(b);print(\"XML well formed\",True)
  for t in root.iter(\"thing\"):
   if t.findtext(\"id\") in (\"Human475\",\"Human478\",\"Human483\"):
    work=t.find(\"workSettings\");time=t.find(\"timetable\");print(\"AFFECTED FIELDS\",dict(id=t.findtext(\"id\"),pos=t.findtext(\"pos\"),drafted=t.findtext(\"drafter/drafted\",\"False\"),job=t.findtext(\"jobs/curJob/def\"),priority_values=[e.text for e in work.findall(\"priorities/vals/li\")],timetable=[e.text for e in time.findall(\"times/li\")]))
 except ET.ParseError as e:print(\"XML well formed\",False,\"error\",str(e))
for d in (\"live-after6\",\"live-after8\",\"live-after9\"):
 j=json.loads((raw/d/\"trunk-doors.json\").read_text());print(\"RESTORE COMPARISON\",d)
 for key in (\"rectangle\",\"pawns\",\"map_pawns\",\"supplement\"):
  a=j.get(\"baseline\",{}).get(key);b=j.get(\"restored\",{}).get(key);print(key,\"baseline_present\",a is not None,\"restored_present\",b is not None,\"equal\",a==b if a is not None else None)
 for phase in (\"baseline\",\"restored\"):
  policies=j.get(phase,{}).get(\"supplement\",{}).get(\"actor_policies\",[])
  print(phase,\"policies\",[{k:x[k] for k in (\"id\",\"pos\",\"drafted\",\"job\")} for x in policies],\"policy_work_hashes\",[hashlib.sha256(x[\"work\"].encode()).hexdigest() for x in policies])
 print(\"INVARIANTS\",[(x[\"phase\"],len(x[\"pawns\"])) for x in j.get(\"original_invariants\",[])])
 print(\"CALLS\",{\"spawn_pawn\":sum(c[\"tool\"]==\"jawa/spawn_pawn\" for c in j[\"calls\"]),\"cut_completed\":any(x[\"phase\"]==\"cut_completed\" for x in j.get(\"original_invariants\",[]))})
PY"

