49:             [ToolParameter(Description = "WorkGiverDef defName (default ConstructDeliverResourcesToBlueprints).")] string workGiver = "ConstructDeliverResourcesToBlueprints")
50:         {
51:             return await ctx.MainThread.InvokeAsync(() =>
52:             {
53:                 Pawn p = FindPawn(pawn, out string perr);
54:                 if (p == null) return Fail(perr);
55:                 Thing t = FindLiveThingById(thing, out string terr);
56:                 if (t == null) return Fail(terr);
57:                 if (!t.Spawned || t.Map != p.Map) return Fail("Thing and pawn are not spawned on the same map.");
58:                 WorkGiverDef wgd = DefDatabase<WorkGiverDef>.GetNamedSilentFail(workGiver ?? "");
59:                 if (wgd == null) return Fail("No WorkGiverDef '" + workGiver + "'.");
60:                 var sc = wgd.Worker as WorkGiver_Scanner;
61:                 if (sc == null) return Fail("WorkGiverDef '" + workGiver + "' worker " + wgd.Worker?.GetType().FullName + " is not a WorkGiver_Scanner.");
62:                 Map map = p.Map;
63:                 var errors = new List<string>();
64:                 Func<string, Func<object>, object> safe = (name, f) =>
65:                 {
66:                     try { return f(); }
67:                     catch (Exception e) { errors.Add(name + ": " + e.GetType().Name + ": " + e.Message); return "threw"; }
68:                 };
69: 
70:                 // BRIDGETOOLS_WORKGIVER_PROBE_ANIMAL_NRE: an animal has no workSettings, and a pawn whose settings were never
71:                 // initialised throws inside WorkIsActive / GetPriority / WorkGiversInOrderNormal; each read is guarded.
72:                 bool? workActive = null; int prio = -1; bool inList = false;
73:                 if (p.workSettings == null) errors.Add("workSettings: pawn has none (animal / non-worker); work gates not applicable");
74:                 else if (wgd.workType != null)
75:                 {
76:                     safe("WorkIsActive", () => workActive = p.workSettings.WorkIsActive(wgd.workType));
77:                     safe("GetPriority", () => prio = p.workSettings.GetPriority(wgd.workType));
78:                     safe("WorkGiversInOrderNormal", () => inList = p.workSettings.WorkGiversInOrderNormal.Contains(wgd.Worker));
79:                 }
80:                 object shouldSkip = safe("ShouldSkip", () => sc.ShouldSkip(p, false));
81:                 object inPotential = safe("PotentialWorkThingsGlobal", () =>
82:                 {
83:                     var pot = sc.PotentialWorkThingsGlobal(p);
84:                     if (pot == null) return (object)"null (uses PotentialWorkThingRequest)";
85:                     return pot.Contains(t);
86:                 });
87:                 object requestAccepts = safe("PotentialWorkThingRequest", () => sc.PotentialWorkThingRequest.Accepts(t));
88:                 PathEndMode pem = sc.PathEndMode;
89:                 Danger danger = sc.MaxPathDanger(p);
90:                 object canReach = safe("CanReach", () => p.CanReach(t, pem, danger));
91:                 object canReachTouchDeadly = safe("CanReachTouch", () => p.CanReach(t, PathEndMode.Touch, Danger.Deadly));
92:                 object canReserve = safe("CanReserve", () => p.CanReserve(t));
93:                 JobFailReason.Clear();
94:                 object hasJob = safe("HasJobOnThing", () => sc.HasJobOnThing(p, t, false));
95:                 string failReason = JobFailReason.Reason;
96:                 JobFailReason.Clear();
97:                 object job = safe("JobOnThing", () => DescribeJob(sc.JobOnThing(p, t, false)));
98:                 string failReason2 = JobFailReason.Reason;
99:                 JobFailReason.Clear();
100: 
101:                 object construction = null;
102:                 if (t is IConstructible ic)
103:                 {
104:                     var c = new Dictionary<string, object>();
105:                     c["canConstruct"] = safe("CanConstruct", () => InvokeFilled(typeof(GenConstruct), "CanConstruct", t, p, wgd.workType));
106:                     c["canConstructFailReason"] = JobFailReason.Reason;
107:                     JobFailReason.Clear();
108:                     c["firstBlockingThing"] = safe("FirstBlockingThing", () => (InvokeFilled(typeof(GenConstruct), "FirstBlockingThing", t, p, wgd.workType) as Thing)?.ThingID ?? "none");
109:                     c["resourceDeliverJobFor"] = !(sc is WorkGiver_ConstructDeliverResources)
110:                         ? "n/a (giver is not a DeliverResources giver)"
111:                         : safe("ResourceDeliverJobFor", () => DescribeJob(InvokeFilled(typeof(WorkGiver_ConstructDeliverResources), "ResourceDeliverJobFor", t, p, wgd.workType, sc) as Job));
112:                     c["resourceDeliverFailReason"] = JobFailReason.Reason;
113:                     JobFailReason.Clear();
114:                     var needs = new List<object>();
115:                     foreach (ThingDefCountClass need in ic.TotalMaterialCost())
116:                     {
117:                         int needed = ic.ThingCountNeeded(need.thingDef);
118:                         if (needed <= 0) continue;
119:                         Thing closest = null;
120:                         safe("ClosestThingReachable", () => closest = GenClosest.ClosestThingReachable(p.Position, map, ThingRequest.ForDef(need.thingDef),
121:                             PathEndMode.ClosestTouch, TraverseParms.For(p, Danger.Deadly, TraverseMode.ByPawn), 9999f));
122:                         var all = map.listerThings.ThingsOfDef(need.thingDef);
123:                         needs.Add(new
124:                         {
125:                             def = need.thingDef.defName,
126:                             needed,
127:                             onMap = all.Sum(x => x.stackCount),
128:                             stacks = all.Take(8).Select(x => new
129:                             {
130:                                 id = x.ThingID, x = x.Position.x, z = x.Position.z, count = x.stackCount,
131:                                 forbidden = x.IsForbidden(p), reach = p.CanReach(x, PathEndMode.ClosestTouch, Danger.Deadly),
132:                                 reserved = map.reservationManager.IsReservedByAnyoneOf(x, p.Faction)
133:                             }).ToList(),
134:                             closestReachable = closest?.ThingID
135:                         });
136:                     }
137:                     c["needs"] = needs;
138:                     construction = c;
139:                 }
140: 
141:                 var neighbours = new List<object>();
142:                 foreach (IntVec3 n in GenAdj.CellsAdjacent8Way(t))
143:                 {
144:                     if (!n.InBounds(map)) continue;
145:                     neighbours.Add(new
146:                     {
147:                         x = n.x, z = n.z, terrain = n.GetTerrain(map)?.defName, standable = n.Standable(map),
148:                         walkable = n.Walkable(map), reachOnCell = p.CanReach(n, PathEndMode.OnCell, Danger.Deadly)
149:                     });
150:                 }
151: 
152:                 object swim = safe("swimProfile", () =>
153:                 {
154:                     Type sw = GenTypes.GetTypeInAnyAssembly("RimMandrake.FlowWorks.Swimming.RM_Swim");
155:                     MethodInfo pof = sw?.GetMethod("ProfileOf", BindingFlags.Public | BindingFlags.Static);
156:                     if (pof == null) return (object)"FlowWorks RM_Swim.ProfileOf not found";
157:                     object pr = pof.Invoke(null, new object[] { p });
158:                     return pr.GetType().GetFields().ToDictionary(f => f.Name, f => (object)f.GetValue(pr)?.ToString());
159:                 });
160: 
161:                 return (object)new
162:                 {
163:                     success = true,
164:                     pawn = p.LabelShort, pawnPos = new { x = p.Position.x, z = p.Position.z },
165:                     pawnJob = p.CurJobDef?.defName, carried = p.carryTracker?.CarriedThing?.ThingID,
166:                     thing = t.ThingID, thingPos = new { x = t.Position.x, z = t.Position.z, sx = t.def.size.x, sz = t.def.size.z },
167:                     workGiver = wgd.defName, worker = sc.GetType().FullName,
168:                     gates = new
169:                     {
170:                         workType = wgd.workType?.defName, workActive, priority = prio, giverInNormalList = inList,
171:                         shouldSkip, inPotential, requestAccepts, forbidden = t.IsForbidden(p),
172:                         pathEndMode = pem.ToString(), maxDanger = danger.ToString(), canReach, canReachTouchDeadly, canReserve,
173:                         hasJobOnThing = hasJob
174:                     },
175:                     failReason, jobOnThingFailReason = failReason2, job, construction, neighbours, swim, errors,
176:                     ticksGame = TicksGameSafe()
177:                 };
178:             }, cancellationToken).ConfigureAwait(false);
179:             // WORKGIVERPROBE_FIX_UNCANCELLABLE_INVOKE: the token was not passed, so a call queued while frames had
180:             // stalled could never be cancelled by the caller and held its bridge request forever.
181:         }
182: 
183:         private static object DescribeJob(Job j)
184:         {
185:             if (j == null) return null;
186:             Func<LocalTargetInfo, string> d = x => !x.IsValid ? null : x.HasThing ? x.Thing.ThingID : x.Cell.ToString();
187:             return new
188:             {
189:                 def = j.def?.defName, count = j.count, targetA = d(j.targetA), targetB = d(j.targetB), targetC = d(j.targetC),
190:                 queueA = j.targetQueueA?.Select(d).ToList(), queueB = j.targetQueueB?.Select(d).ToList()
191:             };
192:         }
193: 
194:         /// <summary>Call the static (or instance, on <paramref name="instance"/>) method <paramref name="name"/> of
195:         /// <paramref name="type"/> with the overload having the most parameters, filling each by type (Thing / IConstructible
196:         /// / Pawn / WorkTypeDef) or its default; anything else unfillable refuses the overload.</summary>
197:         private static object InvokeFilled(Type type, string name, Thing t, Pawn p, WorkTypeDef wt, object instance = null)
198:         {
199:             var flags = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.Instance;
200:             foreach (MethodInfo m in type.GetMethods(flags).Where(m => m.Name == name).OrderByDescending(m => m.GetParameters().Length))
201:             {
202:                 if (!m.IsStatic && instance == null) continue;
203:                 var ps = m.GetParameters();
204:                 var args = new object[ps.Length];
205:                 bool ok = true;
206:                 for (int i = 0; i < ps.Length && ok; i++)
207:                 {
208:                     Type pt = ps[i].ParameterType;
209:                     if (pt == typeof(Pawn)) args[i] = p;
210:                     else if (pt.IsInstanceOfType(t)) args[i] = t;
211:                     else if (pt == typeof(WorkTypeDef)) args[i] = wt;
212:                     else if (ps[i].HasDefaultValue) args[i] = ps[i].DefaultValue;
213:                     else if (pt == typeof(bool)) args[i] = false;
214:                     else if (!pt.IsValueType) args[i] = null;
215:                     else ok = false;

